import React, { useState } from 'react';
import axios from 'axios';
import './App.css';

const App = () => {
  const [terms, setTerms] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  const apiUrl = 'https://k9cvcqnuzg.execute-api.us-west-2.amazonaws.com/dev';

  const handleSearch = async () => {
    if (!searchTerm.trim()) {
      setError('Please enter a search term');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const url = `${apiUrl}/get-definition?term=${encodeURIComponent(searchTerm)}`;
      const response = await axios.get(url);
      
      if (response.status === 200) {
        // Ensure the response has a category (default to 'General' if not provided)
        const termData = {
          ...response.data,
          category: response.data.category || 'General',
          example: response.data.example || '',
          source: response.data.source || 'Cloud Dictionary'
        };
        setTerms([termData]);
      } else if (response.status === 404) {
        setError(response.data.message);
        setTerms([]);
      }
    } catch (error) {
      if (error.response) {
        if (error.response.status === 404) {
          setError(error.response.data.message);
        } else {
          setError('An error occurred while fetching data');
        }
      } else {
        setError('Network error - could not connect to server');
      }
      setTerms([]);
    } finally {
      setLoading(false);
    }
  };

  // TermCard component (moved inside App for better state management)
  const TermCard = ({ term }) => (
    <div className="term-card">
      <div className="term-header">
        <h3 className="term-title">{term.term}</h3>
        <span className={`category-tag ${term.category.toLowerCase()}`}>
          {term.category}
        </span>
      </div>
      <div className="term-body">
        <p className="term-definition">{term.definition}</p>
        {term.example && (
          <div className="term-example">
            <strong>Example: </strong>
            <em>{term.example}</em>
          </div>
        )}
      </div>
      <div className="term-footer">
        <span className="term-source">{term.source}</span>
      </div>
    </div>
  );

  return (
    <div className="App">
      <header className="App-header">
        <h1 className="app-title">Cloud Dictionary</h1>
        <div className="search-container">
          <input
            type="text"
            className="search-input"
            placeholder="Search for a cloud term..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
          />
          <button 
            className="search-button"
            onClick={handleSearch} 
            disabled={loading}
          >
            {loading ? (
              <span className="button-loading">
                <span className="spinner"></span> Searching...
              </span>
            ) : (
              'Search'
            )}
          </button>
        </div>
      </header>
      
      <main className="dictionary-container">
        {error && (
          <div className="error-message">
            <span className="error-icon">⚠️</span> {error}
          </div>
        )}
        
        {loading && (
          <div className="loading-skeleton">
            <div className="skeleton-card"></div>
          </div>
        )}
        
        {!loading && terms.length > 0 && (
          <div className="terms-list">
            {terms.map((term) => (
              <TermCard key={term.term} term={term} />
            ))}
          </div>
        )}
        
        {!loading && terms.length === 0 && !error && (
          <div className="empty-state">
            <div className="empty-icon">🔍</div>
            <h3>No terms found</h3>
            <p>Try searching for a cloud computing term</p>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;
